plist.dict:
    NSPrincipalClass
    TCrCocoaApplication
    CFBundleExecutable
    {{.PList.CFBundleExecutable}}
    CFBundleName
    {{.PList.CFBundleName}}
    CFBundleDisplayName
    {{.PList.CFBundleDisplayName}}
    CFBundleLocalizations
    {{range $i,$value := .PList.CFBundleLocalizations }}
        {{$value}}{{end}}

    CFBundleIdentifier
    {{.PList.CFBundleIdentifier}}
    CFBundleVersion
    {{.PList.CFBundleVersion}}
    CFBundleShortVersionString
    {{.PList.CFBundleShortVersionString}}
    CFBundleGetInfoString
    {{.PList.CFBundleGetInfoString}}
    CFBundleIconFile
    {{.PList.CFBundleIconFile}}
    NSHumanReadableCopyright
    {{.PList.NSHumanReadableCopyright}}
    LSUIElement
    <{{.PList.LSUIElement}}/>
    LSMinimumSystemVersion
    {{.PList.LSMinimumSystemVersion}}
    NSAppTransportSecurity

        NSAllowsArbitraryLoads


    LSHasLocalizedDisplayName

    NSDarkModeAware

    CFBundlePackageType
    APPL
    CFBundleInfoDictionaryVersion
    6.0
    NSHighResolutionCapable

{{- $CFBundleIdentifier := .PList.CFBundleIdentifier}}
{{- if .AssociateFiles}}
    CFBundleDocumentTypes

        {{- range .AssociateFiles}}

            CFBundleTypeName
            {{.CFBundleTypeName}}
            CFBundleTypeRole
            {{.CFBundleTypeRole}}
            LSHandlerRank
            {{.LSHandlerRank}}
            LSItemContentTypes

                {{$CFBundleIdentifier}}.{{.CFBundleTypeExtensions}}

        {{- if .CFBundleTypeIconFile}}
            CFBundleTypeIconFile
            {{.CFBundleTypeIconFile}}
        {{- end}}

        {{- end}}

    UTExportedTypeDeclarations

        {{- range .AssociateFiles}}

            UTTypeIdentifier
            {{$CFBundleIdentifier}}.{{.CFBundleTypeExtensions}}
            UTTypeConformsTo

                public.data

            UTTypeTagSpecification

                public.filename-extension

                    {{.CFBundleTypeExtensions}}

                {{- if .CFBundleTypeMimeType}}
                public.mime-type
                {{.CFBundleTypeMimeType}}
                {{- end}}


        {{- end}}

{{- end}}
{{- if .AssociateProtocols}}
    CFBundleURLTypes

        {{- range .AssociateProtocols}}

            CFBundleURLSchemes

                {{.Scheme}}

            CFBundleURLName
            {{.Description}}

        {{- end}}

{{- end}}
